package com.example.rocketmotionlab
import android.graphics.Bitmap
import android.net.Uri
import androidx.activity.compose.rememberLauncherForActivityResult
import androidx.activity.result.contract.ActivityResultContracts
import androidx.compose.foundation.*
import androidx.compose.foundation.gestures.detectTapGestures
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.*
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.asImageBitmap
import androidx.compose.ui.input.pointer.pointerInput
import androidx.compose.ui.layout.ContentScale
import androidx.compose.ui.unit.dp

enum class Screen{HOME,NEW,CAL,RESULT,COMPARE}
@Composable fun RocketMotionApp(vm:MainViewModel){var s by remember{mutableStateOf(Screen.HOME)};var sel by remember{mutableStateOf(setOf<Long>())};MaterialTheme{Scaffold(topBar={TopAppBar(title={Text("Rocket Motion Lab")},navigationIcon={if(s!=Screen.HOME)TextButton(onClick={s=Screen.HOME}){Text("←")}})}){pad->Box(Modifier.padding(pad).fillMaxSize()){when(s){Screen.HOME->Home(vm.experiments,{s=Screen.NEW},{sel=setOf(it.id);s=Screen.COMPARE},{s=Screen.COMPARE},vm::clear);Screen.NEW->NewExp(vm){s=Screen.CAL};Screen.CAL->Cal(vm);Screen.RESULT->vm.currentResult?.let{Result(it)}?:Text("Sem resultado");Screen.COMPARE->Compare(vm.experiments,sel){id->sel=if(id in sel)sel-id else if(sel.size<3)sel+id else sel}};if(vm.isProcessing)Surface(Modifier.fillMaxSize(),color=MaterialTheme.colorScheme.surface.copy(alpha=.9f)){Box(contentAlignment=Alignment.Center){Column(horizontalAlignment=Alignment.CenterHorizontally){CircularProgressIndicator();Text("Analisando vídeo…")}}}}}};LaunchedEffect(vm.currentResult,vm.isProcessing){if(vm.currentResult!=null&&!vm.isProcessing&&s==Screen.CAL)s=Screen.RESULT}}
@Composable fun Home(exps:List<ExperimentSummary>,new:()->Unit,open:(ExperimentSummary)->Unit,compare:()->Unit,clear:()->Unit){Column(Modifier.padding(20.dp).fillMaxSize()){Text("Laboratório de movimento por vídeo",style=MaterialTheme.typography.headlineSmall);Spacer(Modifier.height(12.dp));Button(new,Modifier.fillMaxWidth()){Text("Adicionar novo experimento")};OutlinedButton(compare,Modifier.fillMaxWidth(),enabled=exps.size>=2){Text("Comparar experimentos")};Spacer(Modifier.height(16.dp));LazyColumn(Modifier.weight(1f)){items(exps){e->Card(Modifier.fillMaxWidth().padding(vertical=4.dp),onClick={open(e)}){Column(Modifier.padding(12.dp)){Text(e.name);Text("Altura ${f(e.maxHeightM)} m • Vel. ${f(e.maxSpeedMs)} m/s • Estab. ${f(e.stabilityIndex)}%")}}}};if(exps.isNotEmpty())TextButton(clear,Modifier.fillMaxWidth()){Text("Apagar histórico")}}}
@Composable fun NewExp(vm:MainViewModel,next:()->Unit){val pick=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){u:Uri?->u?.let(vm::setVideo)};Column(Modifier.padding(20.dp).verticalScroll(rememberScrollState())){Text("Novo experimento",style=MaterialTheme.typography.headlineSmall);OutlinedTextField(vm.draft.experimentName,vm::name,label={Text("Nome")},modifier=Modifier.fillMaxWidth());Spacer(Modifier.height(8.dp));Button({pick.launch(arrayOf("video/*"))},Modifier.fillMaxWidth()){Text(if(vm.draft.videoUri==null)"Selecionar vídeo" else "Trocar vídeo")};Spacer(Modifier.height(8.dp));OutlinedTextField(vm.draft.massGrams,vm::mass,label={Text("Massa total (g) — opcional")},modifier=Modifier.fillMaxWidth());Spacer(Modifier.height(12.dp));Button(next,Modifier.fillMaxWidth(),enabled=vm.draft.videoUri!=null){Text("Calibrar")}}}
@Composable fun Cal(vm:MainViewModel){Column(Modifier.padding(16.dp).verticalScroll(rememberScrollState())){Text("Calibração",style=MaterialTheme.typography.headlineSmall);Text("Toque em dois pontos conhecidos da fita e depois no centro do foguete.");OutlinedTextField(vm.draft.realDistanceMeters,vm::distance,label={Text("Distância real entre os pontos (m)")},modifier=Modifier.fillMaxWidth());Spacer(Modifier.height(8.dp));vm.firstFrame?.let{Picker(it,vm.draft.calibrationA,vm.draft.calibrationB,vm.draft.initialRocketPoint){p->if(vm.draft.calibrationB==null)vm.calibration(p)else vm.rocket(p)}}?:CircularProgressIndicator();Text(when{vm.draft.calibrationA==null->"Marque o 1º ponto da fita";vm.draft.calibrationB==null->"Marque o 2º ponto da fita";vm.draft.initialRocketPoint==null->"Marque o foguete";else->"Pronto para analisar"});Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedButton(vm::reset,Modifier.weight(1f)){Text("Refazer")};Button(vm::analyze,Modifier.weight(1f),enabled=vm.draft.calibrationB!=null&&vm.draft.initialRocketPoint!=null){Text("Analisar")}};vm.error?.let{Text(it,color=MaterialTheme.colorScheme.error)}}}
@Composable fun Picker(b:Bitmap,a:Offset?,c:Offset?,r:Offset?,tap:(Offset)->Unit){Box(Modifier.fillMaxWidth().aspectRatio(b.width.toFloat()/b.height).border(1.dp,MaterialTheme.colorScheme.outline)){Image(b.asImageBitmap(),null,Modifier.fillMaxSize().pointerInput(b){detectTapGestures{q->tap(Offset(q.x*b.width/size.width,q.y*b.height/size.height))}},contentScale=ContentScale.FillBounds);Canvas(Modifier.fillMaxSize()){fun mark(p:Offset?,rad:Float){if(p!=null)drawCircle(androidx.compose.ui.graphics.Color.Black,rad,Offset(p.x/b.width*size.width,p.y/b.height*size.height))};mark(a,8f);mark(c,8f);mark(r,12f)}}}
@Composable fun Result(e:ExperimentSummary){val p=e.points;val t=p.map{it.t};Column(Modifier.padding(16.dp).verticalScroll(rememberScrollState())){Text(e.name,style=MaterialTheme.typography.headlineSmall);Metric("Altura máxima","${f(e.maxHeightM)} m");Metric("Alcance horizontal","${f(e.horizontalRangeM)} m");Metric("Velocidade máxima","${f(e.maxSpeedMs)} m/s");Metric("Aceleração máxima","${f(e.maxAccelMs2)} m/s²");e.maxForceN?.let{Metric("Força máx. estimada","${f(it)} N")};Metric("Estabilidade","${f(e.stabilityIndex)}%");Spacer(Modifier.height(14.dp));LineChart("Trajetória",p.map{it.xM},p.map{it.yM});LineChart("Altura × tempo",t,p.map{it.yM});LineChart("Velocidade × tempo",t,p.map{it.speed});LineChart("Aceleração × tempo",t,p.map{it.accel});if(e.massGrams!=null){LineChart("Força × tempo",t,p.map{it.force?:0.0});LineChart("Energia cinética × tempo",t,p.map{it.kineticEnergy?:0.0});LineChart("Energia potencial × tempo",t,p.map{it.potentialEnergy?:0.0})};Text("As grandezas derivadas são estimativas e dependem da calibração, do FPS e da qualidade do rastreamento.")}}
@Composable fun Metric(a:String,b:String){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(a);Text(b)}}
@Composable fun Compare(exps:List<ExperimentSummary>,sel:Set<Long>,toggle:(Long)->Unit){val s=exps.filter{it.id in sel};Column(Modifier.padding(16.dp).verticalScroll(rememberScrollState())){Text("Comparar experimentos",style=MaterialTheme.typography.headlineSmall);exps.forEach{e->Row(Modifier.fillMaxWidth().clickable{toggle(e.id)},verticalAlignment=Alignment.CenterVertically){Checkbox(e.id in sel,{toggle(e.id)});Text(e.name)}};s.forEach{e->Card(Modifier.fillMaxWidth().padding(4.dp)){Column(Modifier.padding(10.dp)){Text(e.name);Text("Altura ${f(e.maxHeightM)} m • Vel. ${f(e.maxSpeedMs)} m/s • Acel. ${f(e.maxAccelMs2)} m/s²")}}};if(s.size>=2){s.forEach{e->LineChart("${e.name} — altura × tempo",e.points.map{it.t},e.points.map{it.yM})}}}}
fun f(v:Double)=String.format("%.2f",v)
